#include <algorithm>
#include <cctype>
#include <string>
#include <tuple>
#include <vector>

struct Row { int id; std::string kind; int x, y, hp; };

static std::string lower(std::string s)
{
    for (char& c : s) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    return s;
}

std::vector<Row> visibleRows(const std::vector<Row>& rows, const std::string& filter, int column, bool ascending)
{
    const std::string needle{ lower(filter) };
    std::vector<Row> out;
    for (const Row& r : rows)
        if (needle.empty() || lower(r.kind).find(needle) != std::string::npos) out.push_back(r);

    // -1, 0 or 1 comparing the chosen column only.
    auto compare = [column](const Row& a, const Row& b) {
        switch (column)
        {
        case 1: return a.kind < b.kind ? -1 : (b.kind < a.kind ? 1 : 0);
        case 2: return std::tie(a.y, a.x) < std::tie(b.y, b.x) ? -1 : (std::tie(b.y, b.x) < std::tie(a.y, a.x) ? 1 : 0);
        case 3: return a.hp < b.hp ? -1 : (b.hp < a.hp ? 1 : 0);
        default: return a.id < b.id ? -1 : (b.id < a.id ? 1 : 0);
        }
    };
    std::sort(out.begin(), out.end(), [&](const Row& a, const Row& b) {
        const int c{ compare(a, b) };
        if (c != 0) return ascending ? c < 0 : c > 0;
        return a.id < b.id;                                // tie-breaker: always ascending id
    });
    return out;
}

unitTests:
static std::vector<int> ids(const std::vector<Row>& rows) { std::vector<int> v; for (const Row& r : rows) v.push_back(r.id); return v; }
const std::vector<Row> table{ { 4, "Goblin", 3, 1, 10 }, { 1, "Troll", 9, 9, 40 }, { 3, "goblin archer", 1, 1, 10 }, { 2, "Kobold", 5, 0, 7 } };
TEST("by id") { CHECK(ids(visibleRows(table, "", 0, true)) == std::vector<int>({ 1, 2, 3, 4 })); CHECK(ids(visibleRows(table, "", 0, false)) == std::vector<int>({ 4, 3, 2, 1 })); }
TEST("filter ignores case") { CHECK(ids(visibleRows(table, "GOB", 0, true)) == std::vector<int>({ 3, 4 })); }
TEST("by hp with ties broken by id") { CHECK(ids(visibleRows(table, "", 3, true)) == std::vector<int>({ 2, 3, 4, 1 })); CHECK(ids(visibleRows(table, "", 3, false)) == std::vector<int>({ 1, 3, 4, 2 })); }
TEST("by position: y then x") { CHECK(ids(visibleRows(table, "", 2, true)) == std::vector<int>({ 2, 3, 4, 1 })); }
TEST("by kind") { CHECK(ids(visibleRows(table, "", 1, true)) == std::vector<int>({ 4, 2, 1, 3 })); }
TEST("nothing matches") { CHECK(visibleRows(table, "dragon", 0, true).empty()); }

